// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //       }

// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //       if (!round.totalRounds) {
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //         round.totalRounds = wsRoom.totalRounds ?? DEFAULT_WS_GAME_CONFIG.totalRounds;
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //       }

// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //       if (!round.timeLimitSec) {
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //         round.timeLimitSec = wsRoom.timeLimitSec ?? DEFAULT_WS_GAME_CONFIG.timeLimitSec;
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //       }

// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //       setWsGameConfig({
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //         totalRounds: round.totalRounds,
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //         timeLimitSec: round.timeLimitSec,
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //       });

// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //       const lives =
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //         typeof round.lives === "number"
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //           ? round.lives
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //           : typeof wsRoom.lives === "number"
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //           ? wsRoom.lives
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //           : DEFAULT_LIVES;

// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //       setWsLivesLeft(lives);

// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //       // VERY IMPORTANT: save round BEFORE changing screen.
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //       setWsRound(round);

// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //       setGameStartError(null);

// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //       setScreen("wsGame");

// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //       console.log("GAME SCREEN OPENED");
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //     } catch (err: any) {
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //       console.error("START GAME ERROR:", err);

// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //       const message = err?.message ?? "Unable to start the game.";

// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //       setGameStartError(message);

// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //       Alert.alert("Unable to start game", message);
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //     } finally {
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //       setStartingGame(false);
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //     }
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //   }, [wsRoom, startingGame]);

