// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //           }

// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //           if (id === "word-scramble") {
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //             loadTopPlayers();
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //             refreshProfile();
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //             setScreen("wordScrambleHome");
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //           }
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //         }}
