// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //     }

// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //     return (
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //       <GamePlayScreen
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //         playerName={playerName}
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //         round={wsRound as any}
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //         players={(wsRoom?.players ?? []).map((player) => ({
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //           player_name: player.player_name,
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //           score: Number(player.score ?? 0),
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //         }))}
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //         livesLeft={wsLivesLeft}
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //         onRoundEnd={(answer, isCorrect, livesLeft) => {
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //           console.log("ROUND END", {
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //             answer,
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //             isCorrect,
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //             livesLeft,
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //             roundId: wsRound.id,
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //             roundNumber: wsRound.roundNumber,
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //           });

// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //           // Always update lives.
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //           setWsLivesLeft(livesLeft);

// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //           // Correct answer -> show the round complete screen.
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //           if (isCorrect) {
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //             setScreen("roundComplete");
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //             return;
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // // //           }

