// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //     if (key === "settings") {
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //       refreshSettings();
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //       navigation.navigate("Settings");
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //       return;
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //     }
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //     if (key === "help") {
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //       Alert.alert(
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //         "How to play",
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //         "Crack the secret code of 3 pins (digits 1-4, no repeats).\n\n" +
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //           "Green dot = right digit, right slot.\n" +
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //           "Yellow ring = right digit, wrong slot.\n" +
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //           "The counts never say which slot.\n\n" +
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //           "Codes still possible shows how many codes fit your clues."
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //       );
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //     }
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //   };

// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //   const shell = (navigation: any, active: NavKey, node: React.ReactNode) => (
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //     <CodeBreakerShell active={active} onNavigate={makeHandleNav(navigation)}>
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //       {node}
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //     </CodeBreakerShell>
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //   );

