// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //               onCreateRoom={async (config: CreateRoomConfig) => {
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //                 const name = await ensurePlayerName();

// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //                 if (!name) {
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //                   Alert.alert("Player name required", "Unable to load your player profile.");
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //                   return;
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //                 }

// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //                 try {
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //                   const response = await createRoom({
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //                     roomName: config.roomName,
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //                     roomType: config.roomType,
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //                     maxPlayers: config.numberOfPlayers,
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //                     playerName: name,
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //                     difficulty: config.difficulty,
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //                   });

// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //                   const room = extractRoom(response);
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //                   if (!room) throw new Error("Server did not return room data.");

// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //                   setWsRoom(room);
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //                   setWsRound(null);
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //                   setWsLivesLeft(typeof room.lives === "number" ? room.lives : DEFAULT_LIVES);
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //                   setGameStartError(null);

// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //                   navigation.navigate("RoomWaiting");
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //                 } catch (err: any) {
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //                   console.warn("Create room failed:", err);
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //                   Alert.alert("Create room failed", err?.message ?? "Unable to create room.");
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //                 }
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //               }}
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //               onJoinRoom={(code) => handleJoinRoom(navigation, code)}
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //               onTabHome={() => navigation.navigate("WordScrambleHome")}
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //               onTabLeaderboard={() => navigation.navigate("WsLeaderboard")}
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //               onTabProfile={() => navigation.navigate("Menu")}
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //             />
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //           )}
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // //         </Stack.Screen>

