// // // // // // // // // // // // // // // // // // // // // // // // // // // // //   if (!data) return null;
// // // // // // // // // // // // // // // // // // // // // // // // // // // // //   if (data.round) return normalizeRound(data.round);
// // // // // // // // // // // // // // // // // // // // // // // // // // // // //   if (data.data?.round) return normalizeRound(data.data.round);
// // // // // // // // // // // // // // // // // // // // // // // // // // // // //   if (data.data) return normalizeRound(data.data);
// // // // // // // // // // // // // // // // // // // // // // // // // // // // //   return normalizeRound(data);
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // }

// // // // // // // // // // // // // // // // // // // // // // // // // // // // // function normalizeRound(raw: any): WordScrambleRound | null {
// // // // // // // // // // // // // // // // // // // // // // // // // // // // //   if (!raw) return null;

// // // // // // // // // // // // // // // // // // // // // // // // // // // // //   const round: WordScrambleRound = {
// // // // // // // // // // // // // // // // // // // // // // // // // // // // //     ...raw,
// // // // // // // // // // // // // // // // // // // // // // // // // // // // //     id: raw.id ?? raw.roundId ?? raw.round_id ?? null,
// // // // // // // // // // // // // // // // // // // // // // // // // // // // //     roundNumber: Number(raw.roundNumber ?? raw.round_number ?? raw.round ?? 1),
// // // // // // // // // // // // // // // // // // // // // // // // // // // // //     totalRounds: Number(
// // // // // // // // // // // // // // // // // // // // // // // // // // // // //       raw.totalRounds ?? raw.total_rounds ?? DEFAULT_WS_GAME_CONFIG.totalRounds
// // // // // // // // // // // // // // // // // // // // // // // // // // // // //     ),
// // // // // // // // // // // // // // // // // // // // // // // // // // // // //     timeLimitSec: Number(
// // // // // // // // // // // // // // // // // // // // // // // // // // // // //       raw.timeLimitSec ??
// // // // // // // // // // // // // // // // // // // // // // // // // // // // //         raw.time_limit_sec ??
// // // // // // // // // // // // // // // // // // // // // // // // // // // // //         raw.timePerRoundSec ??
// // // // // // // // // // // // // // // // // // // // // // // // // // // // //         raw.time_per_round_sec ??
// // // // // // // // // // // // // // // // // // // // // // // // // // // // //         DEFAULT_WS_GAME_CONFIG.timeLimitSec
// // // // // // // // // // // // // // // // // // // // // // // // // // // // //     ),
// // // // // // // // // // // // // // // // // // // // // // // // // // // // //     word: raw.word ?? raw.answer ?? raw.correctWord ?? raw.correct_word ?? "",
// // // // // // // // // // // // // // // // // // // // // // // // // // // // //     scrambledWord: raw.scrambledWord ?? raw.scrambled_word ?? raw.scrambled ?? "",
// // // // // // // // // // // // // // // // // // // // // // // // // // // // //     scrambled: raw.scrambled ?? raw.scrambledWord ?? raw.scrambled_word ?? "",
// // // // // // // // // // // // // // // // // // // // // // // // // // // // //     clue: raw.clue ?? raw.hint ?? "",
// // // // // // // // // // // // // // // // // // // // // // // // // // // // //   };

// // // // // // // // // // // // // // // // // // // // // // // // // // // // //   return round;
// // // // // // // // // // // // // // // // // // // // // // // // // // // // // }

