// // // // // // // // // // // // // // // // // // // // // // // // // // // //   /* ---------------- word scramble ---------------- */

// // // // // // // // // // // // // // // // // // // // // // // // // // // //   const [wsProfile, setWsProfile] = useState<WsProfile | null>(null);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //   const [topPlayers, setTopPlayers] = useState<TopPlayer[]>([]);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //   const [wsRoom, setWsRoom] = useState<WordScrambleRoom | null>(null);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //   const [wsRound, setWsRound] = useState<WordScrambleRound | null>(null);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //   const [wsGameConfig, setWsGameConfig] = useState(DEFAULT_WS_GAME_CONFIG);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //   const [wsLivesLeft, setWsLivesLeft] = useState<number>(DEFAULT_LIVES);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //   const [startingGame, setStartingGame] = useState(false);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //   const [gameStartError, setGameStartError] = useState<string | null>(null);

// // // // // // // // // // // // // // // // // // // // // // // // // // // //   const playerName = wsProfile?.name ?? "";

// // // // // // // // // // // // // // // // // // // // // // // // // // // //   /* ---------------- initial load ---------------- */

// // // // // // // // // // // // // // // // // // // // // // // // // // // //   useEffect(() => {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     fetchSettings()
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       .then((data) => setSettings(data))
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       .catch((err: unknown) => console.warn("Failed to load settings:", err));

// // // // // // // // // // // // // // // // // // // // // // // // // // // //     fetchStats()
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       .then((data) => setStats(data))
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       .catch((err: unknown) => console.warn("Failed to load stats:", err));
// // // // // // // // // // // // // // // // // // // // // // // // // // // //   }, []);

// // // // // // // // // // // // // // // // // // // // // // // // // // // //   /* ---------------- refresh helpers ---------------- */

// // // // // // // // // // // // // // // // // // // // // // // // // // // //   const refreshStats = useCallback(() => {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     fetchStats()
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       .then((data) => setStats(data))
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       .catch((err: unknown) => console.warn("Failed to refresh stats:", err));
// // // // // // // // // // // // // // // // // // // // // // // // // // // //   }, []);

// // // // // // // // // // // // // // // // // // // // // // // // // // // //   const refreshSettings = useCallback(() => {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     fetchSettings()
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       .then((data) => setSettings(data))
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       .catch((err: unknown) => console.warn("Failed to refresh settings:", err));
// // // // // // // // // // // // // // // // // // // // // // // // // // // //   }, []);

// // // // // // // // // // // // // // // // // // // // // // // // // // // //   const refreshProfile = useCallback(() => {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     fetchProfile()
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       .then((profile) => setWsProfile(profile))
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       .catch((err: unknown) => console.warn("Failed to load profile:", err));
// // // // // // // // // // // // // // // // // // // // // // // // // // // //   }, []);

// // // // // // // // // // // // // // // // // // // // // // // // // // // //   const loadTopPlayers = useCallback(() => {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     fetchLeaderboard()
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       .then((players: any[]) => {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         const formattedPlayers = players.slice(0, 3).map((p: any, index: number) => ({
// // // // // // // // // // // // // // // // // // // // // // // // // // // //           rank: p.rank ?? index + 1,
// // // // // // // // // // // // // // // // // // // // // // // // // // // //           name: p.name ?? p.player_name ?? "Player",
// // // // // // // // // // // // // // // // // // // // // // // // // // // //           score: Number(p.score ?? 0),
// // // // // // // // // // // // // // // // // // // // // // // // // // // //           avatarColor:
// // // // // // // // // // // // // // // // // // // // // // // // // // // //             p.avatarColor ??
// // // // // // // // // // // // // // // // // // // // // // // // // // // //             p.avatar_color ??
// // // // // // // // // // // // // // // // // // // // // // // // // // // //             FALLBACK_AVATAR_COLORS[index] ??
// // // // // // // // // // // // // // // // // // // // // // // // // // // //             "#4F46E5",
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         }));

// // // // // // // // // // // // // // // // // // // // // // // // // // // //         setTopPlayers(formattedPlayers);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       })
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       .catch((err: unknown) => console.warn("Leaderboard failed:", err));
// // // // // // // // // // // // // // // // // // // // // // // // // // // //   }, []);

// // // // // // // // // // // // // // // // // // // // // // // // // // // //   useEffect(() => {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     refreshProfile();
// // // // // // // // // // // // // // // // // // // // // // // // // // // //   }, [refreshProfile]);

// // // // // // // // // // // // // // // // // // // // // // // // // // // //   /* ---------------- ensure player name ---------------- */

// // // // // // // // // // // // // // // // // // // // // // // // // // // //   const ensurePlayerName = useCallback(async (): Promise<string | null> => {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     if (wsProfile?.name) return wsProfile.name;

// // // // // // // // // // // // // // // // // // // // // // // // // // // //     try {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       const profile = await fetchProfile();
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       setWsProfile(profile);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       return profile.name;
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     } catch (err) {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       console.warn("Could not load player:", err);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       return null;
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     }
// // // // // // // // // // // // // // // // // // // // // // // // // // // //   }, [wsProfile]);

// // // // // // // // // // // // // // // // // // // // // // // // // // // //   /* ---------------- code breaker nav helpers ---------------- */
// // // // // // // // // // // // // // // // // // // // // // // // // // // //   // These build the onNavigate callback the Sidebar expects, bound
// // // // // // // // // // // // // // // // // // // // // // // // // // // //   // to whichever screen's `navigation` object is currently active.

// // // // // // // // // // // // // // // // // // // // // // // // // // // //   const makeHandleNav = (navigation: any) => (key: NavKey) => {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     if (key === "home") {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       navigation.navigate("Home");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       return;
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     }
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     if (key === "levels") {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       navigation.navigate("Levels");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       return;
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     }
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     if (key === "settings") {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       refreshSettings();
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       navigation.navigate("Settings");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       return;
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     }
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     if (key === "help") {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       Alert.alert(
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         "How to play",
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         "Crack the secret code of 3 pins (digits 1-4, no repeats).\n\n" +
// // // // // // // // // // // // // // // // // // // // // // // // // // // //           "Green dot = right digit, right slot.\n" +
// // // // // // // // // // // // // // // // // // // // // // // // // // // //           "Yellow ring = right digit, wrong slot.\n" +
// // // // // // // // // // // // // // // // // // // // // // // // // // // //           "The counts never say which slot.\n\n" +
// // // // // // // // // // // // // // // // // // // // // // // // // // // //           "Codes still possible shows how many codes fit your clues."
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       );
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     }
// // // // // // // // // // // // // // // // // // // // // // // // // // // //   };

// // // // // // // // // // // // // // // // // // // // // // // // // // // //   const shell = (navigation: any, active: NavKey, node: React.ReactNode) => (
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     <CodeBreakerShell active={active} onNavigate={makeHandleNav(navigation)}>
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       {node}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     </CodeBreakerShell>
// // // // // // // // // // // // // // // // // // // // // // // // // // // //   );

// // // // // // // // // // // // // // // // // // // // // // // // // // // //   /* ---------------- word scramble nav helpers ---------------- */

// // // // // // // // // // // // // // // // // // // // // // // // // // // //   const makeHandleWsNav = (navigation: any) => (key: WsNavKey) => {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     if (key === "home") {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       loadTopPlayers();
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       refreshProfile();
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       navigation.navigate("WordScrambleHome");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       return;
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     }
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     if (key === "rankings") {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       navigation.navigate("WsLeaderboard");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       return;
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     }
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     if (key === "profile") {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       navigation.navigate("Menu");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     }
// // // // // // // // // // // // // // // // // // // // // // // // // // // //   };

// // // // // // // // // // // // // // // // // // // // // // // // // // // //   const wsShell = (navigation: any, active: WsNavKey, node: React.ReactNode) => (
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     <WordScrambleShell active={active} onNavigate={makeHandleWsNav(navigation)} profile={wsProfile}>
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       {node}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     </WordScrambleShell>
// // // // // // // // // // // // // // // // // // // // // // // // // // // //   );

// // // // // // // // // // // // // // // // // // // // // // // // // // // //   /* ---------------- join room ---------------- */

// // // // // // // // // // // // // // // // // // // // // // // // // // // //   const handleJoinRoom = async (navigation: any, code: string) => {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     const name = await ensurePlayerName();

// // // // // // // // // // // // // // // // // // // // // // // // // // // //     if (!name) {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       Alert.alert("Player name required", "Unable to load your player profile.");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       return;
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     }

// // // // // // // // // // // // // // // // // // // // // // // // // // // //     try {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       const response = await joinRoom(code.trim(), name);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       const room = extractRoom(response);

// // // // // // // // // // // // // // // // // // // // // // // // // // // //       if (!room) {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         throw new Error("Server did not return room information.");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       }

// // // // // // // // // // // // // // // // // // // // // // // // // // // //       setWsRoom(room);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       setWsLivesLeft(typeof room.lives === "number" ? room.lives : DEFAULT_LIVES);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       setWsRound(null);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       setGameStartError(null);

// // // // // // // // // // // // // // // // // // // // // // // // // // // //       navigation.navigate("RoomWaiting");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     } catch (err: any) {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       console.warn("Join room failed:", err);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       Alert.alert("Unable to join room", err?.message ?? "Please check the room code.");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     }
// // // // // // // // // // // // // // // // // // // // // // // // // // // //   };

// // // // // // // // // // // // // // // // // // // // // // // // // // // //   /* ---------------- start word scramble game ---------------- */

// // // // // // // // // // // // // // // // // // // // // // // // // // // //   const handleStartGame = useCallback(
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     async (navigation: any) => {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       if (!wsRoom) {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         Alert.alert("Room not found", "Please create or join a room first.");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         return;
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       }

// // // // // // // // // // // // // // // // // // // // // // // // // // // //       if (startingGame) return;

// // // // // // // // // // // // // // // // // // // // // // // // // // // //       setStartingGame(true);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       setGameStartError(null);

// // // // // // // // // // // // // // // // // // // // // // // // // // // //       try {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         const response = await startGame(wsRoom.roomCode);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         const round = extractRound(response);

// // // // // // // // // // // // // // // // // // // // // // // // // // // //         if (!round) {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //           throw new Error("Backend did not return the first round.");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         }
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         if (round.id === null || round.id === undefined) {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //           throw new Error("Round ID is missing from backend response.");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         }
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         if (!round.roundNumber) round.roundNumber = 1;
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         if (!round.totalRounds) round.totalRounds = wsRoom.totalRounds ?? DEFAULT_WS_GAME_CONFIG.totalRounds;
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         if (!round.timeLimitSec) round.timeLimitSec = wsRoom.timeLimitSec ?? DEFAULT_WS_GAME_CONFIG.timeLimitSec;

// // // // // // // // // // // // // // // // // // // // // // // // // // // //         setWsGameConfig({
// // // // // // // // // // // // // // // // // // // // // // // // // // // //           totalRounds: round.totalRounds,
// // // // // // // // // // // // // // // // // // // // // // // // // // // //           timeLimitSec: round.timeLimitSec,
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         });

// // // // // // // // // // // // // // // // // // // // // // // // // // // //         const lives =
// // // // // // // // // // // // // // // // // // // // // // // // // // // //           typeof round.lives === "number"
// // // // // // // // // // // // // // // // // // // // // // // // // // // //             ? round.lives
// // // // // // // // // // // // // // // // // // // // // // // // // // // //             : typeof wsRoom.lives === "number"
// // // // // // // // // // // // // // // // // // // // // // // // // // // //             ? wsRoom.lives
// // // // // // // // // // // // // // // // // // // // // // // // // // // //             : DEFAULT_LIVES;

// // // // // // // // // // // // // // // // // // // // // // // // // // // //         setWsLivesLeft(lives);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         setWsRound(round);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         setGameStartError(null);

// // // // // // // // // // // // // // // // // // // // // // // // // // // //         navigation.navigate("WsGame");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       } catch (err: any) {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         console.error("START GAME ERROR:", err);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         const message = err?.message ?? "Unable to start the game.";
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         setGameStartError(message);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         Alert.alert("Unable to start game", message);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       } finally {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         setStartingGame(false);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       }
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     },
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     [wsRoom, startingGame]
// // // // // // // // // // // // // // // // // // // // // // // // // // // //   );

// // // // // // // // // // // // // // // // // // // // // // // // // // // //   /* ============================================================
// // // // // // // // // // // // // // // // // // // // // // // // // // // //      RENDER
// // // // // // // // // // // // // // // // // // // // // // // // // // // //   ============================================================ */

// // // // // // // // // // // // // // // // // // // // // // // // // // // //   return (
// // // // // // // // // // // // // // // // // // // // // // // // // // // //     <NavigationContainer linking={linking} fallback={<GameLoadingScreen />}>
// // // // // // // // // // // // // // // // // // // // // // // // // // // //       <Stack.Navigator screenOptions={{ headerShown: false }} initialRouteName="Menu">
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         {/* ---------------- menu ---------------- */}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         <Stack.Screen name="Menu">
// // // // // // // // // // // // // // // // // // // // // // // // // // // //           {({ navigation }) => (
// // // // // // // // // // // // // // // // // // // // // // // // // // // //             <MenuScreen
// // // // // // // // // // // // // // // // // // // // // // // // // // // //               onSelectGame={(id) => {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 if (id === "code-breaker") {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   navigation.navigate("CodeBreakerSplash");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 }
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 if (id === "word-scramble") {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   // CHANGED: go through the new Word Scramble splash first,
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   // instead of jumping straight to WordScrambleHome.
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   navigation.navigate("WordScrambleSplash");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 }
// // // // // // // // // // // // // // // // // // // // // // // // // // // //               }}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //             />
// // // // // // // // // // // // // // // // // // // // // // // // // // // //           )}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         </Stack.Screen>

// // // // // // // // // // // // // // // // // // // // // // // // // // // //         {/* ---------------- code breaker splash ---------------- */}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         <Stack.Screen name="CodeBreakerSplash">
// // // // // // // // // // // // // // // // // // // // // // // // // // // //           {({ navigation }) => (
// // // // // // // // // // // // // // // // // // // // // // // // // // // //             <SplashScreen onFinish={() => navigation.navigate("Home")} />
// // // // // // // // // // // // // // // // // // // // // // // // // // // //           )}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         </Stack.Screen>

// // // // // // // // // // // // // // // // // // // // // // // // // // // //         {/* ---------------- word scramble splash (NEW) ---------------- */}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         <Stack.Screen name="WordScrambleSplash">
// // // // // // // // // // // // // // // // // // // // // // // // // // // //           {({ navigation }) => (
// // // // // // // // // // // // // // // // // // // // // // // // // // // //             <WordScrambleSplashScreen
// // // // // // // // // // // // // // // // // // // // // // // // // // // //               onFinish={() => {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 loadTopPlayers();
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 refreshProfile();
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 // `replace` (not `navigate`) so the splash screen is removed
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 // from the back-stack: pressing back from Home won't return
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 // to the splash animation.
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 navigation.replace("WordScrambleHome");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //               }}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //             />
// // // // // // // // // // // // // // // // // // // // // // // // // // // //           )}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         </Stack.Screen>

// // // // // // // // // // // // // // // // // // // // // // // // // // // //         {/* ---------------- CODE BREAKER: LEVEL MAP ---------------- */}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         <Stack.Screen name="Levels">
// // // // // // // // // // // // // // // // // // // // // // // // // // // //           {({ navigation }) =>
// // // // // // // // // // // // // // // // // // // // // // // // // // // //             shell(
// // // // // // // // // // // // // // // // // // // // // // // // // // // //               navigation,
// // // // // // // // // // // // // // // // // // // // // // // // // // // //               "levels",
// // // // // // // // // // // // // // // // // // // // // // // // // // // //               <LevelMapScreen
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 darkMode={settings.darkMode}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 onBack={() => navigation.navigate("Home")}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 onSelect={(level) => {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   setSelectedLevel(level);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   navigation.navigate("Game");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 }}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //               />
// // // // // // // // // // // // // // // // // // // // // // // // // // // //             )
// // // // // // // // // // // // // // // // // // // // // // // // // // // //           }
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         </Stack.Screen>

// // // // // // // // // // // // // // // // // // // // // // // // // // // //         {/* ---------------- CODE BREAKER: GAME ---------------- */}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         <Stack.Screen name="Game">
// // // // // // // // // // // // // // // // // // // // // // // // // // // //           {({ navigation }) =>
// // // // // // // // // // // // // // // // // // // // // // // // // // // //             shell(
// // // // // // // // // // // // // // // // // // // // // // // // // // // //               navigation,
// // // // // // // // // // // // // // // // // // // // // // // // // // // //               "levels",
// // // // // // // // // // // // // // // // // // // // // // // // // // // //               <GameScreen
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 difficulty={difficulty}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 level={selectedLevel}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 darkMode={settings.darkMode}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 onBack={() => navigation.navigate("Levels")}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 onWin={() => {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   refreshStats();
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   navigation.navigate("Levels");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 }}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 onLose={() => {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   refreshStats();
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   navigation.navigate("Levels");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 }}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //               />
// // // // // // // // // // // // // // // // // // // // // // // // // // // //             )
// // // // // // // // // // // // // // // // // // // // // // // // // // // //           }
