// // // // // // // // // // // // // // // // // // // // // // // // // // // //             if (!wsRoom) {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //               // No room in memory (e.g. page was opened directly at
// // // // // // // // // // // // // // // // // // // // // // // // // // // //               // this URL) -> send them to pick/create one instead.
// // // // // // // // // // // // // // // // // // // // // // // // // // // //               useEffect(() => {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 navigation.navigate("WordScrambleHome");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //               }, []);
