// // // // // // // // // // // // // // // // // // // // // // // // // // // //         <Stack.Screen name="WsGame">
// // // // // // // // // // // // // // // // // // // // // // // // // // // //           {({ navigation }) => {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //             if (!wsRound) {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //               return (
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 <GameErrorScreen
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   message={gameStartError ?? "The server did not return a valid game round."}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   onBack={() => navigation.navigate("RoomWaiting")}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   onRetry={() => handleStartGame(navigation)}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 />
// // // // // // // // // // // // // // // // // // // // // // // // // // // //               );
// // // // // // // // // // // // // // // // // // // // // // // // // // // //             }

// // // // // // // // // // // // // // // // // // // // // // // // // // // //             return (
// // // // // // // // // // // // // // // // // // // // // // // // // // // //               <GamePlayScreen
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 playerName={playerName}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 round={wsRound as any}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 players={(wsRoom?.players ?? []).map((player) => ({
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   player_name: player.player_name,
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   score: Number(player.score ?? 0),
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 }))}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 livesLeft={wsLivesLeft}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 onRoundEnd={(answer, isCorrect, livesLeft) => {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   setWsLivesLeft(livesLeft);

// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   if (isCorrect) {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                     navigation.navigate("RoundComplete");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                     return;
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   }

// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   // Time ran out ("Try Again" tapped) -> lose a life, then
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   // either end the game (no lives left) or reload the SAME
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   // round with a fresh puzzle. Staying on "WsGame" is fine:
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   // GamePlayScreen resets itself whenever round.id changes.
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   if (livesLeft <= 0) {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                     navigation.navigate("WsGameOver");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                     return;
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   }

// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   if (!wsRoom || !wsRound) return;

// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   retryRound(String(wsRound.id), wsRoom.roomCode)
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                     .then((response) => {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                       const retryData = extractRound(response);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                       if (!retryData) throw new Error("Backend did not return the retried round.");

// // // // // // // // // // // // // // // // // // // // // // // // // // // //                       retryData.roundNumber = wsRound.roundNumber;
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                       retryData.totalRounds = wsRound.totalRounds;
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                       retryData.timeLimitSec = wsRound.timeLimitSec;

// // // // // // // // // // // // // // // // // // // // // // // // // // // //                       if (typeof retryData.lives === "number") setWsLivesLeft(retryData.lives);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                       setWsRound(retryData);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                     })
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                     .catch((err: any) => {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                       console.warn("Retry after timeout failed:", err);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                       Alert.alert("Retry failed", err?.message ?? "Unable to load a new round.");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                     });
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 }}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //               />
// // // // // // // // // // // // // // // // // // // // // // // // // // // //             );
// // // // // // // // // // // // // // // // // // // // // // // // // // // //           }}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         </Stack.Screen>

// // // // // // // // // // // // // // // // // // // // // // // // // // // //         {/* ---------------- round complete ---------------- */}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         <Stack.Screen name="RoundComplete">
// // // // // // // // // // // // // // // // // // // // // // // // // // // //           {({ navigation }) => {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //             if (!wsRound) {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //               useEffect(() => {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 navigation.navigate("WordScrambleHome");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //               }, []);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //               return <GameLoadingScreen />;
// // // // // // // // // // // // // // // // // // // // // // // // // // // //             }

// // // // // // // // // // // // // // // // // // // // // // // // // // // //             return (
// // // // // // // // // // // // // // // // // // // // // // // // // // // //               <RoundCompleteScreen
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 roundId={Number(wsRound.id)}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 playerName={playerName}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 onNextRound={async (isCorrect: boolean) => {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   if (!wsRoom) {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                     console.warn("Cannot continue: room missing.");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                     return;
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   }
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   if (wsRound.id === null || wsRound.id === undefined) {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                     Alert.alert("Round error", "Round ID is missing.");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                     return;
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   }

// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   try {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                     if (isCorrect) {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                       const response = await nextRound(wsRoom.roomCode);

// // // // // // // // // // // // // // // // // // // // // // // // // // // //                       if (response?.finished === true || response?.gameFinished === true) {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                         setWsRound(null);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                         navigation.navigate("WsGameOver");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                         return;
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                       }

// // // // // // // // // // // // // // // // // // // // // // // // // // // //                       const nextRoundData = extractRound(response);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                       if (!nextRoundData) throw new Error("Backend did not return the next round.");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                       if (nextRoundData.id === null || nextRoundData.id === undefined) {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                         throw new Error("Next round ID is missing.");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                       }

// // // // // // // // // // // // // // // // // // // // // // // // // // // //                       if (!nextRoundData.roundNumber) nextRoundData.roundNumber = wsRound.roundNumber + 1;
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                       if (!nextRoundData.totalRounds) nextRoundData.totalRounds = wsRound.totalRounds ?? wsGameConfig.totalRounds;
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                       if (!nextRoundData.timeLimitSec) nextRoundData.timeLimitSec = wsRound.timeLimitSec ?? wsGameConfig.timeLimitSec;

// // // // // // // // // // // // // // // // // // // // // // // // // // // //                       setWsRound(nextRoundData);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                       if (typeof nextRoundData.lives === "number") setWsLivesLeft(nextRoundData.lives);

// // // // // // // // // // // // // // // // // // // // // // // // // // // //                       navigation.navigate("WsGame");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                       return;
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                     }

// // // // // // // // // // // // // // // // // // // // // // // // // // // //                     const response = await retryRound(String(wsRound.id), wsRoom.roomCode);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                     const retryData = extractRound(response);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                     if (!retryData) throw new Error("Backend did not return the retried round.");

// // // // // // // // // // // // // // // // // // // // // // // // // // // //                     retryData.roundNumber = wsRound.roundNumber;
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                     retryData.totalRounds = wsRound.totalRounds;
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                     retryData.timeLimitSec = wsRound.timeLimitSec;

// // // // // // // // // // // // // // // // // // // // // // // // // // // //                     if (typeof retryData.lives === "number") setWsLivesLeft(retryData.lives);

// // // // // // // // // // // // // // // // // // // // // // // // // // // //                     setWsRound(retryData);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                     navigation.navigate("WsGame");
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   } catch (err: any) {
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                     console.warn(isCorrect ? "Next round failed:" : "Retry failed:", err);
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                     Alert.alert(
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                       isCorrect ? "Next round failed" : "Retry failed",
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                       err?.message ?? "Unable to load the round."
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                     );
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                   }
// // // // // // // // // // // // // // // // // // // // // // // // // // // //                 }}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //               />
// // // // // // // // // // // // // // // // // // // // // // // // // // // //             );
// // // // // // // // // // // // // // // // // // // // // // // // // // // //           }}
// // // // // // // // // // // // // // // // // // // // // // // // // // // //         </Stack.Screen>

