// // // // // // // // // // // // // // // // // // // // // // // // // //               if (!wsRound) {
// // // // // // // // // // // // // // // // // // // // // // // // // //                 useEffect(() => {
// // // // // // // // // // // // // // // // // // // // // // // // // //                   navigation.navigate("WordScrambleHome");
// // // // // // // // // // // // // // // // // // // // // // // // // //                 }, []);
