// // // // // // // // // // // // // // // // // // // // // // // // // /**
// // // // // // // // // // // // // // // // // // // // // // // // //  * Hooks must never be called inside an `if`. This tiny component owns the
// // // // // // // // // // // // // // // // // // // // // // // // //  * redirect effect so the route render functions below stay hook-free.
// // // // // // // // // // // // // // // // // // // // // // // // //  */
// // // // // // // // // // // // // // // // // // // // // // // // // function RedirectTo({ navigation, to }: { navigation: any; to: string }) {
// // // // // // // // // // // // // // // // // // // // // // // // //   useEffect(() => {
// // // // // // // // // // // // // // // // // // // // // // // // //     navigation.navigate(to);
// // // // // // // // // // // // // // // // // // // // // // // // //     // eslint-disable-next-line react-hooks/exhaustive-deps
// // // // // // // // // // // // // // // // // // // // // // // // //   }, []);
// // // // // // // // // // // // // // // // // // // // // // // // //   return <GameLoadingScreen />;
// // // // // // // // // // // // // // // // // // // // // // // // // }

