// // // // // // // // // // // // // // // // // // // // // // // // //                   loadTopPlayers();
// // // // // // // // // // // // // // // // // // // // // // // // //                   refreshProfile();
// // // // // // // // // // // // // // // // // // // // // // // // //                   // `replace` removes the splash from the back-stack
// // // // // // // // // // // // // // // // // // // // // // // // //                   navigation.replace("WordScrambleHome");
// // // // // // // // // // // // // // // // // // // // // // // // //                 }}
// // // // // // // // // // // // // // // // // // // // // // // // //               />
// // // // // // // // // // // // // // // // // // // // // // // // //             )}
// // // // // // // // // // // // // // // // // // // // // // // // //           </Stack.Screen>

