// // // // // // // // // // // // // // // // // // // // // // // // function GameLoadingScreen() {
// // // // // // // // // // // // // // // // // // // // // // // //   return (
// // // // // // // // // // // // // // // // // // // // // // // //     <View style={styles.loadingContainer}>
// // // // // // // // // // // // // // // // // // // // // // // //       <ActivityIndicator size="large" color="#4F46E5" />
// // // // // // // // // // // // // // // // // // // // // // // //       <Text style={styles.loadingTitle}>Starting game...</Text>
// // // // // // // // // // // // // // // // // // // // // // // //       <Text style={styles.loadingText}>Preparing your first round</Text>
// // // // // // // // // // // // // // // // // // // // // // // //     </View>
// // // // // // // // // // // // // // // // // // // // // // // //   );
// // // // // // // // // // // // // // // // // // // // // // // // }

// // // // // // // // // // // // // // // // // // // // // // // // /**
// // // // // // // // // // // // // // // // // // // // // // // //  * Hooks must never be called inside an `if`. This tiny component owns the
// // // // // // // // // // // // // // // // // // // // // // // //  * redirect effect so the route render functions below stay hook-free.
// // // // // // // // // // // // // // // // // // // // // // // //  */
// // // // // // // // // // // // // // // // // // // // // // // // function RedirectTo({ navigation, to }: { navigation: any; to: string }) {
// // // // // // // // // // // // // // // // // // // // // // // //   useEffect(() => {
// // // // // // // // // // // // // // // // // // // // // // // //     navigation.navigate(to);
// // // // // // // // // // // // // // // // // // // // // // // //     // eslint-disable-next-line react-hooks/exhaustive-deps
// // // // // // // // // // // // // // // // // // // // // // // //   }, []);
// // // // // // // // // // // // // // // // // // // // // // // //   return <GameLoadingScreen />;
// // // // // // // // // // // // // // // // // // // // // // // // }

// // // // // // // // // // // // // // // // // // // // // // // // function GameErrorScreen({
// // // // // // // // // // // // // // // // // // // // // // // //   message,
// // // // // // // // // // // // // // // // // // // // // // // //   onBack,
// // // // // // // // // // // // // // // // // // // // // // // //   onRetry,
// // // // // // // // // // // // // // // // // // // // // // // // }: {
// // // // // // // // // // // // // // // // // // // // // // // //   message: string;
// // // // // // // // // // // // // // // // // // // // // // // //   onBack: () => void;
// // // // // // // // // // // // // // // // // // // // // // // //   onRetry: () => void;
// // // // // // // // // // // // // // // // // // // // // // // // }) {
// // // // // // // // // // // // // // // // // // // // // // // //   return (
// // // // // // // // // // // // // // // // // // // // // // // //     <View style={styles.errorContainer}>
// // // // // // // // // // // // // // // // // // // // // // // //       <Text style={styles.errorIcon}>!</Text>
// // // // // // // // // // // // // // // // // // // // // // // //       <Text style={styles.errorTitle}>Unable to start game</Text>
// // // // // // // // // // // // // // // // // // // // // // // //       <Text style={styles.errorMessage}>{message}</Text>

// // // // // // // // // // // // // // // // // // // // // // // //       <View style={styles.errorButton}>
// // // // // // // // // // // // // // // // // // // // // // // //         <Text style={styles.errorButtonText} onPress={onRetry}>
// // // // // // // // // // // // // // // // // // // // // // // //           Try Again
// // // // // // // // // // // // // // // // // // // // // // // //         </Text>
// // // // // // // // // // // // // // // // // // // // // // // //       </View>

// // // // // // // // // // // // // // // // // // // // // // // //       <Text style={styles.backText} onPress={onBack}>
// // // // // // // // // // // // // // // // // // // // // // // //         Back to room
// // // // // // // // // // // // // // // // // // // // // // // //       </Text>
// // // // // // // // // // // // // // // // // // // // // // // //     </View>
// // // // // // // // // // // // // // // // // // // // // // // //   );
// // // // // // // // // // // // // // // // // // // // // // // // }

