// // // // // // // // // // // // // // // // // // // // // // // // 					setWsLivesLeft(typeof room.lives === "number" ? room.lives : DEFAULT_LIVES);

// // // // // // // // // // // // // // // // // // // // // // // // 					if (room.status === "in_progress") {
// // // // // // // // // // // // // // // // // // // // // // // // 						const response = await startGame(room.roomCode || roomCode);
// // // // // // // // // // // // // // // // // // // // // // // // 						const round = extractRound(response);
// // // // // // // // // // // // // // // // // // // // // // // // 						if (!round) throw new Error("The active round could not be restored.");

// // // // // // // // // // // // // // // // // // // // // // // // 						if (!round.totalRounds) round.totalRounds = room.totalRounds ?? DEFAULT_WS_GAME_CONFIG.totalRounds;
// // // // // // // // // // // // // // // // // // // // // // // // 						if (!round.timeLimitSec) round.timeLimitSec = room.timeLimitSec ?? DEFAULT_WS_GAME_CONFIG.timeLimitSec;
// // // // // // // // // // // // // // // // // // // // // // // // 						setWsGameConfig({ totalRounds: round.totalRounds, timeLimitSec: round.timeLimitSec });
// // // // // // // // // // // // // // // // // // // // // // // // 						setWsLivesLeft(typeof round.lives === "number" ? round.lives : room.lives ?? DEFAULT_LIVES);
// // // // // // // // // // // // // // // // // // // // // // // // 						setWsRound(round);
// // // // // // // // // // // // // // // // // // // // // // // // 						restoredRoute = "WsGame";
// // // // // // // // // // // // // // // // // // // // // // // // 					} else if (room.status === "waiting") {
// // // // // // // // // // // // // // // // // // // // // // // // 						setWsRound(null);
// // // // // // // // // // // // // // // // // // // // // // // // 						restoredRoute = "RoomWaiting";
// // // // // // // // // // // // // // // // // // // // // // // // 					} else if (room.status === "finished") {
// // // // // // // // // // // // // // // // // // // // // // // // 						setWsRound(null);
// // // // // // // // // // // // // // // // // // // // // // // // 						restoredRoute = "WsGameOver";
// // // // // // // // // // // // // // // // // // // // // // // // 					}
// // // // // // // // // // // // // // // // // // // // // // // // 				}
// // // // // // // // // // // // // // // // // // // // // // // // 			} catch (err) {
// // // // // // // // // // // // // // // // // // // // // // // // 				console.warn("Could not restore Word Scramble session:", err);
// // // // // // // // // // // // // // // // // // // // // // // // 			} finally {
// // // // // // // // // // // // // // // // // // // // // // // // 				if (!cancelled) {
// // // // // // // // // // // // // // // // // // // // // // // // 					setInitialRouteName(restoredRoute);
// // // // // // // // // // // // // // // // // // // // // // // // 					setSessionRestoreReady(true);
// // // // // // // // // // // // // // // // // // // // // // // // 				}
// // // // // // // // // // // // // // // // // // // // // // // // 			}
// // // // // // // // // // // // // // // // // // // // // // // // 		};

// // // // // // // // // // // // // // // // // // // // // // // // 		restoreWordScrambleSession();
// // // // // // // // // // // // // // // // // // // // // // // // 		return () => {
// // // // // // // // // // // // // // // // // // // // // // // // 			cancelled = true;
// // // // // // // // // // // // // // // // // // // // // // // // 		};
// // // // // // // // // // // // // // // // // // // // // // // // 	}, []);

// // // // // // // // // // // // // // // // // // // // // // // //   /* ---------------- code breaker nav helpers ---------------- */

// // // // // // // // // // // // // // // // // // // // // // // //   const makeHandleNav = (navigation: any) => (key: NavKey) => {
