// // // // // // // // // // // // // // // // // // // // // // // //     }
// // // // // // // // // // // // // // // // // // // // // // // //   };

// // // // // // // // // // // // // // // // // // // // // // // //   const wsShell = (navigation: any, active: WsNavKey, node: React.ReactNode) => (
// // // // // // // // // // // // // // // // // // // // // // // //     <WordScrambleShell active={active} onNavigate={makeHandleWsNav(navigation)} profile={wsProfile}>
// // // // // // // // // // // // // // // // // // // // // // // //       {node}
