// // // // // // // // // // // // // // // // // // // // // // // //   );

// // // // // // // // // // // // // // // // // // // // // // // //   /* ---------------- join room ---------------- */

// // // // // // // // // // // // // // // // // // // // // // // //   const handleJoinRoom = async (navigation: any, code: string) => {
// // // // // // // // // // // // // // // // // // // // // // // //     const name = await ensurePlayerName();

// // // // // // // // // // // // // // // // // // // // // // // //     if (!name) {
// // // // // // // // // // // // // // // // // // // // // // // //       Alert.alert("Player name required", "Unable to load your player profile.");
// // // // // // // // // // // // // // // // // // // // // // // //       return;
// // // // // // // // // // // // // // // // // // // // // // // //     }

// // // // // // // // // // // // // // // // // // // // // // // //     try {
// // // // // // // // // // // // // // // // // // // // // // // //       const response = await joinRoom(code.trim(), name);
// // // // // // // // // // // // // // // // // // // // // // // //       const room = extractRoom(response);

// // // // // // // // // // // // // // // // // // // // // // // //       if (!room) {
// // // // // // // // // // // // // // // // // // // // // // // //         throw new Error("Server did not return room information.");
// // // // // // // // // // // // // // // // // // // // // // // //       }

// // // // // // // // // // // // // // // // // // // // // // // //       setWsRoom(room);
// // // // // // // // // // // // // // // // // // // // // // // // 	await rememberWordScrambleRoom(room.roomCode);
// // // // // // // // // // // // // // // // // // // // // // // //       setWsLivesLeft(typeof room.lives === "number" ? room.lives : DEFAULT_LIVES);
// // // // // // // // // // // // // // // // // // // // // // // //       setWsRound(null);
// // // // // // // // // // // // // // // // // // // // // // // //       setGameStartError(null);

// // // // // // // // // // // // // // // // // // // // // // // //       navigation.navigate("RoomWaiting");
// // // // // // // // // // // // // // // // // // // // // // // //     } catch (err: any) {
// // // // // // // // // // // // // // // // // // // // // // // //       console.warn("Join room failed:", err);
// // // // // // // // // // // // // // // // // // // // // // // //       Alert.alert("Unable to join room", err?.message ?? "Please check the room code.");
// // // // // // // // // // // // // // // // // // // // // // // //     }
// // // // // // // // // // // // // // // // // // // // // // // //   };

// // // // // // // // // // // // // // // // // // // // // // // //   /* ---------------- start word scramble game ---------------- */

// // // // // // // // // // // // // // // // // // // // // // // //   const handleStartGame = useCallback(
// // // // // // // // // // // // // // // // // // // // // // // //     async (navigation: any) => {
// // // // // // // // // // // // // // // // // // // // // // // //       if (!wsRoom) {
// // // // // // // // // // // // // // // // // // // // // // // //         Alert.alert("Room not found", "Please create or join a room first.");
// // // // // // // // // // // // // // // // // // // // // // // //         return;
// // // // // // // // // // // // // // // // // // // // // // // //       }

// // // // // // // // // // // // // // // // // // // // // // // //       if (startingGame) return;

// // // // // // // // // // // // // // // // // // // // // // // //       setStartingGame(true);
// // // // // // // // // // // // // // // // // // // // // // // //       setGameStartError(null);

// // // // // // // // // // // // // // // // // // // // // // // //       try {
// // // // // // // // // // // // // // // // // // // // // // // //         const response = await startGame(wsRoom.roomCode);
// // // // // // // // // // // // // // // // // // // // // // // //         const round = extractRound(response);

// // // // // // // // // // // // // // // // // // // // // // // //         if (!round) {
// // // // // // // // // // // // // // // // // // // // // // // //           throw new Error("Backend did not return the first round.");
// // // // // // // // // // // // // // // // // // // // // // // //         }
// // // // // // // // // // // // // // // // // // // // // // // //         if (round.id === null || round.id === undefined) {
// // // // // // // // // // // // // // // // // // // // // // // //           throw new Error("Round ID is missing from backend response.");
// // // // // // // // // // // // // // // // // // // // // // // //         }
// // // // // // // // // // // // // // // // // // // // // // // //         if (!round.roundNumber) round.roundNumber = 1;
// // // // // // // // // // // // // // // // // // // // // // // //         if (!round.totalRounds) round.totalRounds = wsRoom.totalRounds ?? DEFAULT_WS_GAME_CONFIG.totalRounds;
// // // // // // // // // // // // // // // // // // // // // // // //         if (!round.timeLimitSec) round.timeLimitSec = wsRoom.timeLimitSec ?? DEFAULT_WS_GAME_CONFIG.timeLimitSec;

// // // // // // // // // // // // // // // // // // // // // // // //         setWsGameConfig({
// // // // // // // // // // // // // // // // // // // // // // // //           totalRounds: round.totalRounds,
// // // // // // // // // // // // // // // // // // // // // // // //           timeLimitSec: round.timeLimitSec,
// // // // // // // // // // // // // // // // // // // // // // // //         });

// // // // // // // // // // // // // // // // // // // // // // // //         const lives =
// // // // // // // // // // // // // // // // // // // // // // // //           typeof round.lives === "number"
// // // // // // // // // // // // // // // // // // // // // // // //             ? round.lives
// // // // // // // // // // // // // // // // // // // // // // // //             : typeof wsRoom.lives === "number"
// // // // // // // // // // // // // // // // // // // // // // // //             ? wsRoom.lives
// // // // // // // // // // // // // // // // // // // // // // // //             : DEFAULT_LIVES;

// // // // // // // // // // // // // // // // // // // // // // // //         setWsLivesLeft(lives);
// // // // // // // // // // // // // // // // // // // // // // // //         setWsRound(round);
// // // // // // // // // // // // // // // // // // // // // // // //         setGameStartError(null);

// // // // // // // // // // // // // // // // // // // // // // // //         navigation.navigate("WsGame");
// // // // // // // // // // // // // // // // // // // // // // // //       } catch (err: any) {
// // // // // // // // // // // // // // // // // // // // // // // //         console.error("START GAME ERROR:", err);
// // // // // // // // // // // // // // // // // // // // // // // //         const message = err?.message ?? "Unable to start the game.";
// // // // // // // // // // // // // // // // // // // // // // // //         setGameStartError(message);
// // // // // // // // // // // // // // // // // // // // // // // //         Alert.alert("Unable to start game", message);
// // // // // // // // // // // // // // // // // // // // // // // //       } finally {
// // // // // // // // // // // // // // // // // // // // // // // //         setStartingGame(false);
// // // // // // // // // // // // // // // // // // // // // // // //       }
// // // // // // // // // // // // // // // // // // // // // // // //     },
// // // // // // // // // // // // // // // // // // // // // // // //     [wsRoom, startingGame]
// // // // // // // // // // // // // // // // // // // // // // // //   );

// // // // // // // // // // // // // // // // // // // // // // // //   /* ---------------- go straight to the next round ---------------- */

// // // // // // // // // // // // // // // // // // // // // // // //   const advanceToNextRound = useCallback(
// // // // // // // // // // // // // // // // // // // // // // // //     async (navigation: any) => {
// // // // // // // // // // // // // // // // // // // // // // // //       if (!wsRoom || !wsRound) return;

// // // // // // // // // // // // // // // // // // // // // // // //       try {
// // // // // // // // // // // // // // // // // // // // // // // //         const response = await nextRound(wsRoom.roomCode);
// // // // // // // // // // // // // // // // // // // // // // // //         console.log("nextRound() response:", JSON.stringify(response));

// // // // // // // // // // // // // // // // // // // // // // // //         if (response?.finished === true || response?.gameFinished === true) {
// // // // // // // // // // // // // // // // // // // // // // // //           setWsRound(null);
// // // // // // // // // // // // // // // // // // // // // // // //           navigation.navigate("WsGameOver");
// // // // // // // // // // // // // // // // // // // // // // // //           return;
// // // // // // // // // // // // // // // // // // // // // // // //         }

// // // // // // // // // // // // // // // // // // // // // // // //         const nextRoundData = extractRound(response);
// // // // // // // // // // // // // // // // // // // // // // // //         if (!nextRoundData) throw new Error("Backend did not return the next round.");
// // // // // // // // // // // // // // // // // // // // // // // //         if (nextRoundData.id === null || nextRoundData.id === undefined) {
// // // // // // // // // // // // // // // // // // // // // // // //           throw new Error("Next round ID is missing.");
// // // // // // // // // // // // // // // // // // // // // // // //         }

// // // // // // // // // // // // // // // // // // // // // // // //         if (!nextRoundData.roundNumber) nextRoundData.roundNumber = wsRound.roundNumber + 1;
// // // // // // // // // // // // // // // // // // // // // // // //         if (!nextRoundData.totalRounds) {
// // // // // // // // // // // // // // // // // // // // // // // //           nextRoundData.totalRounds = wsRound.totalRounds ?? wsGameConfig.totalRounds;
// // // // // // // // // // // // // // // // // // // // // // // //         }
// // // // // // // // // // // // // // // // // // // // // // // //         if (!nextRoundData.timeLimitSec) {
// // // // // // // // // // // // // // // // // // // // // // // //           nextRoundData.timeLimitSec = wsRound.timeLimitSec ?? wsGameConfig.timeLimitSec;
// // // // // // // // // // // // // // // // // // // // // // // //         }

// // // // // // // // // // // // // // // // // // // // // // // //         // Guard: a payload with no letters AND no word would blank the screen.
// // // // // // // // // // // // // // // // // // // // // // // //         const hasLetters = Array.isArray(nextRoundData.letters) && nextRoundData.letters.length > 0;
// // // // // // // // // // // // // // // // // // // // // // // //         const hasWord = !!(nextRoundData.word || nextRoundData.scrambled || nextRoundData.scrambledWord);
// // // // // // // // // // // // // // // // // // // // // // // //         if (!hasLetters && !hasWord) {
// // // // // // // // // // // // // // // // // // // // // // // //           throw new Error("The next round's puzzle data was empty.");
// // // // // // // // // // // // // // // // // // // // // // // //         }

// // // // // // // // // // // // // // // // // // // // // // // //         if (typeof nextRoundData.lives === "number") setWsLivesLeft(nextRoundData.lives);
// // // // // // // // // // // // // // // // // // // // // // // //         setWsRound(nextRoundData);
// // // // // // // // // // // // // // // // // // // // // // // //       } catch (err: any) {
// // // // // // // // // // // // // // // // // // // // // // // //         console.warn("Next round failed:", err);
// // // // // // // // // // // // // // // // // // // // // // // //         Alert.alert("Next round failed", err?.message ?? "Unable to load the next round.");
// // // // // // // // // // // // // // // // // // // // // // // //       }
// // // // // // // // // // // // // // // // // // // // // // // //     },
// // // // // // // // // // // // // // // // // // // // // // // //     [wsRoom, wsRound, wsGameConfig]
// // // // // // // // // // // // // // // // // // // // // // // //   );

// // // // // // // // // // // // // // // // // // // // // // // //   /* ============================================================
// // // // // // // // // // // // // // // // // // // // // // // //      RENDER
// // // // // // // // // // // // // // // // // // // // // // // //   ============================================================ */

// // // // // // // // // // // // // // // // // // // // // // // // 	if (!sessionRestoreReady) return <GameLoadingScreen />;

// // // // // // // // // // // // // // // // // // // // // // // //   return (
// // // // // // // // // // // // // // // // // // // // // // // //     <ErrorBoundary label="Word Scramble">
// // // // // // // // // // // // // // // // // // // // // // // //       <NavigationContainer linking={linking} fallback={<GameLoadingScreen />}>
// // // // // // // // // // // // // // // // // // // // // // // // 				<Stack.Navigator screenOptions={{ headerShown: false }} initialRouteName={initialRouteName}>
// // // // // // // // // // // // // // // // // // // // // // // //           {/* ---------------- menu (Cyber Mind home) ---------------- */}
