// // // // // // // // // // // // // // // // // // // // // // // //             {({ navigation }) => (
// // // // // // // // // // // // // // // // // // // // // // // //               <MenuScreen
// // // // // // // // // // // // // // // // // // // // // // // //                 bestScore={stats.highScore}
// // // // // // // // // // // // // // // // // // // // // // // //                 streak={stats.currentStreak}
// // // // // // // // // // // // // // // // // // // // // // // //                 onSelectGame={(id) => {
// // // // // // // // // // // // // // // // // // // // // // // //                   if (id === "code-breaker") {
// // // // // // // // // // // // // // // // // // // // // // // //                     navigation.navigate("CodeBreakerSplash");
// // // // // // // // // // // // // // // // // // // // // // // //                   }
// // // // // // // // // // // // // // // // // // // // // // // //                   if (id === "word-scramble") {
