// // // // // // // // // // // // // // // // // // // // // // //             );

// // // // // // // // // // // // // // // // // // // // // // //           console.log(
// // // // // // // // // // // // // // // // // // // // // // //             "nextRound() response:",
// // // // // // // // // // // // // // // // // // // // // // //             JSON.stringify(response)
// // // // // // // // // // // // // // // // // // // // // // //           );

// // // // // // // // // // // // // // // // // // // // // // //           if (
// // // // // // // // // // // // // // // // // // // // // // //             response?.finished ===
// // // // // // // // // // // // // // // // // // // // // // //               true ||
// // // // // // // // // // // // // // // // // // // // // // //             response?.gameFinished ===
// // // // // // // // // // // // // // // // // // // // // // //               true
