// // // // // // // // // // // // // // // // // // // // // // //             extractRound(response);

// // // // // // // // // // // // // // // // // // // // // // //           if (!nextRoundData) {
// // // // // // // // // // // // // // // // // // // // // // //             throw new Error(
// // // // // // // // // // // // // // // // // // // // // // //               "Backend did not return the next round."
// // // // // // // // // // // // // // // // // // // // // // //             );
// // // // // // // // // // // // // // // // // // // // // // //           }

// // // // // // // // // // // // // // // // // // // // // // //           if (
// // // // // // // // // // // // // // // // // // // // // // //             nextRoundData.id ===
// // // // // // // // // // // // // // // // // // // // // // //               null ||
// // // // // // // // // // // // // // // // // // // // // // //             nextRoundData.id ===
// // // // // // // // // // // // // // // // // // // // // // //               undefined
// // // // // // // // // // // // // // // // // // // // // // //           ) {
