// // // // // // // // // // // // // // // // // // // // // //             extractRound(response);

// // // // // // // // // // // // // // // // // // // // // //           if (!round) {
// // // // // // // // // // // // // // // // // // // // // //             throw new Error(
// // // // // // // // // // // // // // // // // // // // // //               "Backend did not return the first round."
// // // // // // // // // // // // // // // // // // // // // //             );
// // // // // // // // // // // // // // // // // // // // // //           }

// // // // // // // // // // // // // // // // // // // // // //           if (
// // // // // // // // // // // // // // // // // // // // // //             round.id === null ||
// // // // // // // // // // // // // // // // // // // // // //             round.id === undefined
// // // // // // // // // // // // // // // // // // // // // //           ) {
// // // // // // // // // // // // // // // // // // // // // //             throw new Error(
// // // // // // // // // // // // // // // // // // // // // //               "Round ID is missing from backend response."
// // // // // // // // // // // // // // // // // // // // // //             );
// // // // // // // // // // // // // // // // // // // // // //           }

// // // // // // // // // // // // // // // // // // // // // //           if (!round.roundNumber) {
// // // // // // // // // // // // // // // // // // // // // //             round.roundNumber = 1;
// // // // // // // // // // // // // // // // // // // // // //           }

// // // // // // // // // // // // // // // // // // // // // //           if (!round.totalRounds) {
// // // // // // // // // // // // // // // // // // // // // //             round.totalRounds =
// // // // // // // // // // // // // // // // // // // // // //               wsRoom.totalRounds ??
// // // // // // // // // // // // // // // // // // // // // //               DEFAULT_WS_GAME_CONFIG.totalRounds;
// // // // // // // // // // // // // // // // // // // // // //           }

// // // // // // // // // // // // // // // // // // // // // //           if (!round.timeLimitSec) {
// // // // // // // // // // // // // // // // // // // // // //             round.timeLimitSec =
// // // // // // // // // // // // // // // // // // // // // //               wsRoom.timeLimitSec ??
// // // // // // // // // // // // // // // // // // // // // //               DEFAULT_WS_GAME_CONFIG.timeLimitSec;
// // // // // // // // // // // // // // // // // // // // // //           }

// // // // // // // // // // // // // // // // // // // // // //           setWsGameConfig({
// // // // // // // // // // // // // // // // // // // // // //             totalRounds:
// // // // // // // // // // // // // // // // // // // // // //               round.totalRounds,

// // // // // // // // // // // // // // // // // // // // // //             timeLimitSec:
// // // // // // // // // // // // // // // // // // // // // //               round.timeLimitSec,
// // // // // // // // // // // // // // // // // // // // // //           });

// // // // // // // // // // // // // // // // // // // // // //           const lives =
// // // // // // // // // // // // // // // // // // // // // //             typeof round.lives ===
// // // // // // // // // // // // // // // // // // // // // //             "number"
// // // // // // // // // // // // // // // // // // // // // //               ? round.lives
// // // // // // // // // // // // // // // // // // // // // //               : typeof wsRoom.lives ===
// // // // // // // // // // // // // // // // // // // // // //                 "number"
// // // // // // // // // // // // // // // // // // // // // //               ? wsRoom.lives
// // // // // // // // // // // // // // // // // // // // // //               : DEFAULT_LIVES;

// // // // // // // // // // // // // // // // // // // // // //           setWsLivesLeft(lives);

// // // // // // // // // // // // // // // // // // // // // //           setWsRound(round);

// // // // // // // // // // // // // // // // // // // // // //           setGameStartError(null);

// // // // // // // // // // // // // // // // // // // // // //           navigation.navigate(
// // // // // // // // // // // // // // // // // // // // // //             "WsGame"
// // // // // // // // // // // // // // // // // // // // // //           );
// // // // // // // // // // // // // // // // // // // // // //         } catch (err: any) {
// // // // // // // // // // // // // // // // // // // // // //           console.error(
// // // // // // // // // // // // // // // // // // // // // //             "START GAME ERROR:",
// // // // // // // // // // // // // // // // // // // // // //             err
// // // // // // // // // // // // // // // // // // // // // //           );

// // // // // // // // // // // // // // // // // // // // // //           const message =
// // // // // // // // // // // // // // // // // // // // // //             err?.message ??
// // // // // // // // // // // // // // // // // // // // // //             "Unable to start the game.";

// // // // // // // // // // // // // // // // // // // // // //           setGameStartError(message);

// // // // // // // // // // // // // // // // // // // // // //           Alert.alert(
// // // // // // // // // // // // // // // // // // // // // //             "Unable to start game",
// // // // // // // // // // // // // // // // // // // // // //             message
// // // // // // // // // // // // // // // // // // // // // //           );
// // // // // // // // // // // // // // // // // // // // // //         } finally {
// // // // // // // // // // // // // // // // // // // // // //           setStartingGame(false);
// // // // // // // // // // // // // // // // // // // // // //         }
// // // // // // // // // // // // // // // // // // // // // //       },
// // // // // // // // // // // // // // // // // // // // // //       [wsRoom, startingGame]
// // // // // // // // // // // // // // // // // // // // // //     );

// // // // // // // // // // // // // // // // // // // // // //   /* ============================================================
// // // // // // // // // // // // // // // // // // // // // //      NEXT ROUND
// // // // // // // // // // // // // // // // // // // // // //   ============================================================ */

// // // // // // // // // // // // // // // // // // // // // //   const advanceToNextRound =
// // // // // // // // // // // // // // // // // // // // // //     useCallback(
// // // // // // // // // // // // // // // // // // // // // //       async (navigation: any, skipAhead = 0) => {
// // // // // // // // // // // // // // // // // // // // // //         if (!wsRoom || !wsRound) {
// // // // // // // // // // // // // // // // // // // // // //           return;
// // // // // // // // // // // // // // // // // // // // // //         }

// // // // // // // // // // // // // // // // // // // // // //         try {
// // // // // // // // // // // // // // // // // // // // // //           const response =
// // // // // // // // // // // // // // // // // // // // // //             await nextRound(wsRoom.roomCode, {
// // // // // // // // // // // // // // // // // // // // // //               fromRoundId: wsRound.id,
// // // // // // // // // // // // // // // // // // // // // //               skip: skipAhead,
// // // // // // // // // // // // // // // // // // // // // //             });

// // // // // // // // // // // // // // // // // // // // // //           console.log(
// // // // // // // // // // // // // // // // // // // // // //             "nextRound() response:",
// // // // // // // // // // // // // // // // // // // // // //             JSON.stringify(response)
// // // // // // // // // // // // // // // // // // // // // //           );

// // // // // // // // // // // // // // // // // // // // // //           if (
// // // // // // // // // // // // // // // // // // // // // //             response?.finished ===
// // // // // // // // // // // // // // // // // // // // // //               true ||
// // // // // // // // // // // // // // // // // // // // // //             response?.gameFinished ===
// // // // // // // // // // // // // // // // // // // // // //               true
// // // // // // // // // // // // // // // // // // // // // //           ) {
// // // // // // // // // // // // // // // // // // // // // //             setWsRound(null);

// // // // // // // // // // // // // // // // // // // // // //             navigation.navigate(
// // // // // // // // // // // // // // // // // // // // // //               "WsGameOver"
// // // // // // // // // // // // // // // // // // // // // //             );

// // // // // // // // // // // // // // // // // // // // // //             return;
// // // // // // // // // // // // // // // // // // // // // //           }

// // // // // // // // // // // // // // // // // // // // // //           const nextRoundData =
// // // // // // // // // // // // // // // // // // // // // //             extractRound(response);

// // // // // // // // // // // // // // // // // // // // // //           if (!nextRoundData) {
// // // // // // // // // // // // // // // // // // // // // //             throw new Error(
// // // // // // // // // // // // // // // // // // // // // //               "Backend did not return the next round."
// // // // // // // // // // // // // // // // // // // // // //             );
// // // // // // // // // // // // // // // // // // // // // //           }

// // // // // // // // // // // // // // // // // // // // // //           if (
// // // // // // // // // // // // // // // // // // // // // //             nextRoundData.id ===
// // // // // // // // // // // // // // // // // // // // // //               null ||
// // // // // // // // // // // // // // // // // // // // // //             nextRoundData.id ===
// // // // // // // // // // // // // // // // // // // // // //               undefined
// // // // // // // // // // // // // // // // // // // // // //           ) {
// // // // // // // // // // // // // // // // // // // // // //             throw new Error(
// // // // // // // // // // // // // // // // // // // // // //               "Next round ID is missing."
// // // // // // // // // // // // // // // // // // // // // //             );
// // // // // // // // // // // // // // // // // // // // // //           }

// // // // // // // // // // // // // // // // // // // // // //           if (
// // // // // // // // // // // // // // // // // // // // // //             !nextRoundData.roundNumber
// // // // // // // // // // // // // // // // // // // // // //           ) {
// // // // // // // // // // // // // // // // // // // // // //             nextRoundData.roundNumber =
// // // // // // // // // // // // // // // // // // // // // //               wsRound.roundNumber + 1;
// // // // // // // // // // // // // // // // // // // // // //           }

// // // // // // // // // // // // // // // // // // // // // //           if (
// // // // // // // // // // // // // // // // // // // // // //             !nextRoundData.totalRounds
// // // // // // // // // // // // // // // // // // // // // //           ) {
// // // // // // // // // // // // // // // // // // // // // //             nextRoundData.totalRounds =
// // // // // // // // // // // // // // // // // // // // // //               wsRound.totalRounds ??
// // // // // // // // // // // // // // // // // // // // // //               wsGameConfig.totalRounds;
// // // // // // // // // // // // // // // // // // // // // //           }

// // // // // // // // // // // // // // // // // // // // // //           if (
// // // // // // // // // // // // // // // // // // // // // //             !nextRoundData.timeLimitSec
// // // // // // // // // // // // // // // // // // // // // //           ) {
// // // // // // // // // // // // // // // // // // // // // //             nextRoundData.timeLimitSec =
// // // // // // // // // // // // // // // // // // // // // //               wsRound.timeLimitSec ??
// // // // // // // // // // // // // // // // // // // // // //               wsGameConfig.timeLimitSec;
// // // // // // // // // // // // // // // // // // // // // //           }

// // // // // // // // // // // // // // // // // // // // // //           const hasLetters =
// // // // // // // // // // // // // // // // // // // // // //             Array.isArray(
// // // // // // // // // // // // // // // // // // // // // //               nextRoundData.letters
// // // // // // // // // // // // // // // // // // // // // //             ) &&
// // // // // // // // // // // // // // // // // // // // // //             nextRoundData.letters
// // // // // // // // // // // // // // // // // // // // // //               .length > 0;

// // // // // // // // // // // // // // // // // // // // // //           const hasWord =
// // // // // // // // // // // // // // // // // // // // // //             !!(
// // // // // // // // // // // // // // // // // // // // // //               nextRoundData.word ||
// // // // // // // // // // // // // // // // // // // // // //               nextRoundData.scrambled ||
// // // // // // // // // // // // // // // // // // // // // //               nextRoundData.scrambledWord
// // // // // // // // // // // // // // // // // // // // // //             );

// // // // // // // // // // // // // // // // // // // // // //           if (
// // // // // // // // // // // // // // // // // // // // // //             !hasLetters &&
// // // // // // // // // // // // // // // // // // // // // //             !hasWord
// // // // // // // // // // // // // // // // // // // // // //           ) {
// // // // // // // // // // // // // // // // // // // // // //             throw new Error(
// // // // // // // // // // // // // // // // // // // // // //               "The next round's puzzle data was empty."
// // // // // // // // // // // // // // // // // // // // // //             );
// // // // // // // // // // // // // // // // // // // // // //           }

// // // // // // // // // // // // // // // // // // // // // //           if (
// // // // // // // // // // // // // // // // // // // // // //             typeof nextRoundData.lives ===
// // // // // // // // // // // // // // // // // // // // // //             "number"
// // // // // // // // // // // // // // // // // // // // // //           ) {
// // // // // // // // // // // // // // // // // // // // // //             setWsLivesLeft(
// // // // // // // // // // // // // // // // // // // // // //               nextRoundData.lives
// // // // // // // // // // // // // // // // // // // // // //             );
// // // // // // // // // // // // // // // // // // // // // //           }

// // // // // // // // // // // // // // // // // // // // // //           setWsRound(
// // // // // // // // // // // // // // // // // // // // // //             nextRoundData
// // // // // // // // // // // // // // // // // // // // // //           );
// // // // // // // // // // // // // // // // // // // // // //         } catch (err: any) {
// // // // // // // // // // // // // // // // // // // // // //           console.warn(
// // // // // // // // // // // // // // // // // // // // // //             "Next round failed:",
// // // // // // // // // // // // // // // // // // // // // //             err
// // // // // // // // // // // // // // // // // // // // // //           );

// // // // // // // // // // // // // // // // // // // // // //           Alert.alert(
// // // // // // // // // // // // // // // // // // // // // //             "Next round failed",
// // // // // // // // // // // // // // // // // // // // // //             err?.message ??
// // // // // // // // // // // // // // // // // // // // // //               "Unable to load the next round."
// // // // // // // // // // // // // // // // // // // // // //           );
// // // // // // // // // // // // // // // // // // // // // //         }
// // // // // // // // // // // // // // // // // // // // // //       },
// // // // // // // // // // // // // // // // // // // // // //       [
// // // // // // // // // // // // // // // // // // // // // //         wsRoom,
// // // // // // // // // // // // // // // // // // // // // //         wsRound,
// // // // // // // // // // // // // // // // // // // // // //         wsGameConfig,
// // // // // // // // // // // // // // // // // // // // // //       ]
// // // // // // // // // // // // // // // // // // // // // //     );

