// // // // // // // // // // // // // // // // // // // // //      CODE BREAKER NAV
// // // // // // // // // // // // // // // // // // // // //   ============================================================ */

// // // // // // // // // // // // // // // // // // // // //   const makeHandleNav = (navigation: any) => (key: NavKey) => {
// // // // // // // // // // // // // // // // // // // // //     feedback("tap");

// // // // // // // // // // // // // // // // // // // // //     if (key === "home") {
// // // // // // // // // // // // // // // // // // // // //       refreshCbPlayer();

// // // // // // // // // // // // // // // // // // // // //       navigation.navigate("Home");

// // // // // // // // // // // // // // // // // // // // //       return;
// // // // // // // // // // // // // // // // // // // // //     }

// // // // // // // // // // // // // // // // // // // // //     if (key === "levels") {
// // // // // // // // // // // // // // // // // // // // //       navigation.navigate("Levels");

// // // // // // // // // // // // // // // // // // // // //       return;
// // // // // // // // // // // // // // // // // // // // //     }

// // // // // // // // // // // // // // // // // // // // //     if (key === "settings") {
// // // // // // // // // // // // // // // // // // // // //       refreshSettings();

// // // // // // // // // // // // // // // // // // // // //       navigation.navigate("Settings");

// // // // // // // // // // // // // // // // // // // // //       return;
