// // // // // // // // // // // // // // // // // // // // //     if (key === "home") {
// // // // // // // // // // // // // // // // // // // // //       loadTopPlayers();

// // // // // // // // // // // // // // // // // // // // //       refreshProfile();

// // // // // // // // // // // // // // // // // // // // //       navigation.navigate("WordScrambleHome");

// // // // // // // // // // // // // // // // // // // // //       return;
