// // // // // // // // // // // // // // // // // // // // //     }
// // // // // // // // // // // // // // // // // // // // //   };

// // // // // // // // // // // // // // // // // // // // //   const wsShell = (
// // // // // // // // // // // // // // // // // // // // //     navigation: any,
// // // // // // // // // // // // // // // // // // // // //     active: WsNavKey,
// // // // // // // // // // // // // // // // // // // // //     node: React.ReactNode
// // // // // // // // // // // // // // // // // // // // //   ) => (
