// // // // // // // // // // // // // // // // // // // // //               CODE BREAKER HOME
// // // // // // // // // // // // // // // // // // // // //           ===================================================== */}

// // // // // // // // // // // // // // // // // // // // //           <Stack.Screen name="Home">
// // // // // // // // // // // // // // // // // // // // //             {({ navigation }) =>
// // // // // // // // // // // // // // // // // // // // //               shell(
// // // // // // // // // // // // // // // // // // // // //                 navigation,
// // // // // // // // // // // // // // // // // // // // //                 "home",
// // // // // // // // // // // // // // // // // // // // //                 <HomeScreen
// // // // // // // // // // // // // // // // // // // // //                   highScore={stats.highScore}
// // // // // // // // // // // // // // // // // // // // //                   gamesPlayed={stats.gamesPlayed}
// // // // // // // // // // // // // // // // // // // // //                   successRate={
// // // // // // // // // // // // // // // // // // // // //                     stats.gamesPlayed > 0
// // // // // // // // // // // // // // // // // // // // //                       ? Math.round((stats.gamesWon / stats.gamesPlayed) * 100)
// // // // // // // // // // // // // // // // // // // // //                       : 0
// // // // // // // // // // // // // // // // // // // // //                   }
// // // // // // // // // // // // // // // // // // // // //                   playerName={cbPlayerName}
// // // // // // // // // // // // // // // // // // // // //                   darkMode={settings.darkMode}
// // // // // // // // // // // // // // // // // // // // //                   onPlay={() => {
// // // // // // // // // // // // // // // // // // // // //                     feedback("tap");

// // // // // // // // // // // // // // // // // // // // //                     navigation.navigate("Levels");
// // // // // // // // // // // // // // // // // // // // //                   }}
// // // // // // // // // // // // // // // // // // // // //                   onStats={() => {
// // // // // // // // // // // // // // // // // // // // //                     feedback("tap");

