// // // // // // // // // // // // // // // // // // // //               roomCode = active?.roomCode ?? null;
// // // // // // // // // // // // // // // // // // // //             }
// // // // // // // // // // // // // // // // // // // //           } catch {}
// // // // // // // // // // // // // // // // // // // //         }

// // // // // // // // // // // // // // // // // // // //         if (roomCode) {
// // // // // // // // // // // // // // // // // // // //           const [roomResponse, profile] = await Promise.all([
// // // // // // // // // // // // // // // // // // // //             fetchRoom(roomCode),
// // // // // // // // // // // // // // // // // // // //             fetchProfile(),
// // // // // // // // // // // // // // // // // // // //           ]);

// // // // // // // // // // // // // // // // // // // //           const room = extractRoom(roomResponse);

// // // // // // // // // // // // // // // // // // // //           if (!room || !profile?.name) {
